import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Form, Table, Button, Modal, Divider, Row, notification, Spin } from 'antd'
import { filter } from 'lodash'

import { AddFormConfigStyle } from './index.style'
import { FormColumns } from './data'
import AddForm from './addForm'
import ClaimsAction from '../../../../redux/claims/actions'
import LoadingActions from '../../../../../redux/loading/actions'
import ErrorActions from '../../../../../redux/error/actions'

const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions

const { searchAttribute, getFormDetail, createConfig, getConfigTemplateValidation, getRegexList, updateClaimConfigData } = ClaimsAction

class AddConfig extends Component {
  constructor(props) {
    super(props)
    this.state = {
      formData: this.props.formData || [],
      showAddForm: false,
      bankFormRequired: false,
      configName: '',
      responsesProvided: {},
      editData: {},
      edit: false,
      editID: '',
      selectedAttributes: this.getSelectedAttributes()
    }
  }

  getSelectedAttributes = () => {
    const { formData = [] } = this.props
    const selectedAttribute = []
    formData.forEach(form => {
      selectedAttribute.push(...form.attributes)
    })
    return selectedAttribute
  }

  componentDidMount() {
    this.props.searchAttribute()
    this.props.getRegexList()
    this.props.resetLoadingRedux(['GET_CONFIG_TEMPLATES_VALIDATIONS'])
    this.props.resetErrorRedux(['GET_CONFIG_TEMPLATES_VALIDATIONS'])
  }

  UNSAFE_componentWillReceiveProps(nextProps) {
    const {
      validationLoading,
      validationError,
      claimConfigDumpIdMessage
    } = nextProps
    const { responsesProvided, formData } = this.state

    if (validationLoading === false) {
      if (validationError === false) {
        notification.success({ message: claimConfigDumpIdMessage })
        this.props.saveResponse(responsesProvided, formData)
        this.props.handleNext()
      } else {
        notification.error({ message: claimConfigDumpIdMessage })
      }
      this.props.resetLoadingRedux(['GET_CONFIG_TEMPLATES_VALIDATIONS'])
      this.props.resetErrorRedux(['GET_CONFIG_TEMPLATES_VALIDATIONS'])
    }
  }

  handleSubmit = () => {
    const { claimsConfigTemplatesDetails, benefitId, configDumpId, validationData = {}, inprogressConfig = {} } = this.props

    const { formData } = this.state
    if (!formData.length) {
      return notification.error({ message: 'Please add form to continue' })
    }

    const responsesProvided = {}
    responsesProvided[0] = {}
    const simpleClaimForm = filter(formData, { formType: 'claim' })
    const partialClaimForm = filter(formData, { formType: 'partial' })
    responsesProvided[0].form_data = simpleClaimForm
    responsesProvided[0].salvage_data = filter(formData, { formType: 'salvage' })
    responsesProvided[0].partial_data = filter(formData, { formType: 'partial' })
    const selectedAttributes = []

    simpleClaimForm.forEach(element => {
      selectedAttributes.push(...element.attributes)
    })

    partialClaimForm.forEach(element => {
      selectedAttributes.push(...element.attributes)
    })

    this.props.updateClaimConfigData({
      selectedClaimsFormAttribute: selectedAttributes
    })

    this.setState({ responsesProvided })

    this.props.getConfigTemplateValidation({
      body: {
        current_pointer: '0',
        responses_provided: responsesProvided,
        template_id: claimsConfigTemplatesDetails.template_id || inprogressConfig.template_id,
        template_version_id: claimsConfigTemplatesDetails.template_version_id || inprogressConfig.template_version_id,
        benefit_id: benefitId,
        config_dump_id: configDumpId || validationData.config_dump_id || inprogressConfig.config_dump_id
      }
    })
  }

  handleAddForm = () => {
    this.setState({ showAddForm: true })
  }

  handleCancel = () => {
    this.setState({ showAddForm: false, edit: false, editData: {}, editID: '' })
  }

  saveFormData = (data, id) => {
    const { formData } = this.state
    if (id !== '') {
      formData[id] = data
    } else {
      formData.push(data)
    }

    const selectedAttributes = []
    formData.forEach(element => {
      selectedAttributes.push(...element.attributes)
    })

    this.setState({ formData, edit: false, editData: {}, editID: '', selectedAttributes })
  }

  editForm = (data, id) => {
    this.setState({ showAddForm: true, edit: true, editData: data, editID: id })
  }

  deleteForm = (index) => {
    const { formData } = this.state
    const selectedAttributes = []
    const formDataArray = [...formData]
    formDataArray.splice(index, 1)

    formDataArray.forEach(element => {
      selectedAttributes.push(...element.attributes)
    })
    this.setState({ formData: formDataArray, selectedAttributes })
  }

  render() {
    const { validationLoading, configState, partner, checkThisAliasExist, deleteAliasFromLocalArray } = this.props
    const { formData = [], showAddForm, editData, editID = {}, selectedAttributes } = this.state

    return (
      <AddFormConfigStyle>
        <Spin spinning={!!validationLoading}>
          <Modal
            title={Object.keys(editData).length > 0 ? 'Edit Form' : 'Add Form'}
            visible={showAddForm}
            onCancel={this.handleCancel}
            width={850}
            footer={null}
          >
            <AddForm
              onHandleCancel={this.handleCancel}
              saveFormData={this.saveFormData}
              editData={editData}
              editID={editID}
              selectedAttributes={selectedAttributes}
              configState={configState}
              partner={partner}
              checkThisAliasExist={checkThisAliasExist}
              deleteAliasFromLocalArray={deleteAliasFromLocalArray}
            />
          </Modal>
          <div className='heading'>Forms</div>
          <Table
            columns={FormColumns(this)}
            dataSource={formData}
            pagination={false}
          />
          <Button
            type='primary'
            onClick={this.handleAddForm}
          >
            Add Form
          </Button>
          <Divider />

          <Row type='flex' justify='end'>
            <Button
              type='primary'
              onClick={this.handleSubmit}
            >
              Next
            </Button>
          </Row>
        </Spin>
      </AddFormConfigStyle>
    )
  }
}

const WrappedAddForm = Form.create()(AddConfig)

export default connect(state => ({
  createConfigLoading: state.Loading.CREATE_CONFIG,
  createConfigError: state.Error.CREATE_CONFIG,
  createConfigStatus: state.Claims.createConfigStatus,

  claimsConfigTemplatesDetails: state.Claims.claimsConfigTemplatesDetails,

  validationLoading: state.Loading.GET_CONFIG_TEMPLATES_VALIDATIONS,
  validationError: state.Error.GET_CONFIG_TEMPLATES_VALIDATIONS,
  claimConfigDumpIdMessage: state.Claims.claimConfigDumpIdMessage,

  validationData: state.Claims.claimConfigDumpId
}), {
  searchAttribute,
  getFormDetail,
  createConfig,
  getConfigTemplateValidation,
  getRegexList,
  updateClaimConfigData,
  resetLoadingRedux,
  resetErrorRedux
})(WrappedAddForm)
