import { Table } from 'antd'
import { DndProvider, DragSource, DropTarget } from 'react-dnd'
import { HTML5Backend } from 'react-dnd-html5-backend'
import { SelectedAttributesColumns } from '../../data'
import { SelectedAtrributesTableWrapper } from './index.style'

let dragingIndex = -1

const BodyRow = (props) => {
  const { isOver, connectDragSource, connectDropTarget, moveRow, ...restProps } = props
  const style = { ...restProps.style, cursor: 'move' }

  let { className } = restProps
  if (isOver) {
    if (restProps.index > dragingIndex) {
      className += ' drop-over-downward'
    }
    if (restProps.index < dragingIndex) {
      className += ' drop-over-upward'
    }
  }

  return connectDragSource(
    connectDropTarget(<tr {...restProps} className={className} style={style} />)
  )
}

const rowSource = {
  beginDrag (props) {
    dragingIndex = props.index
    return {
      index: props.index
    }
  }
}

const rowTarget = {
  drop (props, monitor) {
    const dragIndex = monitor.getItem().index
    const hoverIndex = props.index

    // Don't replace items with themselves
    if (dragIndex === hoverIndex) {
      return
    }

    // Time to actually perform the action
    props.moveRow(dragIndex, hoverIndex)

    // Note: we're mutating the monitor item here!
    // Generally it's better to avoid mutations,
    // but it's good here for the sake of performance
    // to avoid expensive index searches.
    monitor.getItem().index = hoverIndex
  }
}

const DragableBodyRow = DropTarget('row', rowTarget, (connect, monitor) => ({
  connectDropTarget: connect.dropTarget(),
  isOver: monitor.isOver()
}))(
  DragSource('row', rowSource, connect => ({
    connectDragSource: connect.dragSource()
  }))(BodyRow)
)

const SelectedAttributesTable = ({ classInstanceThis, regexList, dataSource }) => {
  const components = {
    body: {
      row: DragableBodyRow
    }
  }
  const moveRow = (dragIndex, hoverIndex) => {
    const { selectedAttributes } = classInstanceThis.state
    const dragRow = selectedAttributes[dragIndex]
    const clonedSelectedAttributes = [...selectedAttributes]
    clonedSelectedAttributes.splice(dragIndex, 1)
    clonedSelectedAttributes.splice(hoverIndex, 0, dragRow)
    classInstanceThis.setState({
      ...classInstanceThis.state,
      selectedAttributes: clonedSelectedAttributes
    })
  }

  return (
    <SelectedAtrributesTableWrapper>
      <DndProvider backend={HTML5Backend}>
        <Table
          columns={SelectedAttributesColumns(classInstanceThis, regexList)}
          dataSource={dataSource}
          pagination={false}
          locale={{ emptyText: 'Select document from below to add' }}
          components={components}
          onRow={(record, index) => ({
            index,
            moveRow: moveRow
          })}
        />
      </DndProvider>
    </SelectedAtrributesTableWrapper>
  )
}
export default SelectedAttributesTable
