import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Card, Steps, Icon, Divider, notification, Button, Spin } from 'antd'
import { get } from 'lodash'

import { AddConfigStyle } from './index.style'
import AddForm from './addFormConfig'
import ChooseTemplate from './chooseTemplate'
import Questionnaire from './questionnaire'
import Review from './review'
import ClaimsAction from '../../../../redux/claims/actions'
import LoadingActions from '../../../../../redux/loading/actions'
import ErrorActions from '../../../../../redux/error/actions'
import { findAndReplaceKey } from './helpers'

const { Step } = Steps

const { getInprogressConfig, getPolicyFormAttributes, updateClaimConfigData, getConfigTemplates, getConfigTemplateDetails } = ClaimsAction
const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions

const CONFIGSTATES = {
  'ADD': 'ADD',
  'EDIT': 'EDIT',
  'INPROGRESS': 'INPROGRESS'
}

class AddConfig extends Component {
  constructor(props) {
    super(props)
    this.state = {
      stepsConfig: [
        { title: 'Choose Template', status: 'process', icon: 'container' },
        { title: 'Add Forms', status: 'wait', icon: 'form' },
        { title: 'Questionnaire', status: 'wait', icon: 'control' },
        { title: 'Review', status: 'wait', icon: 'check-circle' }
      ],
      current: 0,
      benefitId: '',
      configData: [],
      inprogressConfig: undefined,
      source: '',
      configSlug: undefined,
      configState: CONFIGSTATES['ADD'],
      editData: undefined,
      questions: undefined,
      responsesProvided: undefined,
      aliasChosenByPO: [],
    }
  }

  componentDidMount() {
    const { location = {} } = this.props
    const { state = {} } = location
    this.props.getConfigTemplates(({ query: { source: location.state.source } }))
    if (!state['id']) {
      this.props.history.replace('/claims/onboarding/')
      return
    } else if (state['configData']) {
      this.setState({ configState: CONFIGSTATES['EDIT'], configData: state['configData'] })
      this.handleEditConfigData(state['configData'])
    } else {
      this.props.getInprogressConfig({
        query: {
          benefit_id: state['id']
        }
      })
    }
    this.setState({
      benefitId: state['id'],
      partner: state.selectedPartner,
      source: state['source']
    })
    this.props.getPolicyFormAttributes({
      query: {
        product_key: get(state, 'productKey')
      }
    })

    this.props.resetErrorRedux(['GET_INPROGRESS_CONFIG'])
    this.props.resetLoadingRedux(['GET_INPROGRESS_CONFIG'])
  }

  componentWillReceiveProps(nextProps) {
    const {
      inprogressConfigLoading,
      inprogressConfigError,
      inprogressConfigStatus
    } = nextProps

    if (inprogressConfigLoading === false) {
      if (inprogressConfigError) {
        notification['error']({ message: inprogressConfigStatus })
        this.props.history.replace('/claims/onboarding/')
      }
      this.props.resetErrorRedux(['GET_INPROGRESS_CONFIG'])
      this.props.resetLoadingRedux(['GET_INPROGRESS_CONFIG'])
    }
  }

  handleInprogressConfigData = (inprogressConfig = {}) => {
    const { config_dump_data: configDumpData = {} } = inprogressConfig
    const { responses_provided: responsesProvided, questions } = configDumpData
    let formData = responsesProvided[0] ? responsesProvided[0]['form_data'] : []
    // let salvageData = responsesProvided[0] ? responsesProvided[0]['salvage_data'] : []
    // salvageData.forEach(element => { element.is_salvage = true })
    let salvageData = responsesProvided[0] ? get(responsesProvided[0], 'salvage_data', []) : []
    let partialData = responsesProvided[0] ? get(responsesProvided[0], 'partial_data', []) : []
    formData.forEach(element => {
      element.formType = 'claim'
      return true
    })
    salvageData.forEach(element => {
      element.formType = 'salvage'
      return true
    })
    partialData.forEach(element => {
      element.formType = 'partial'
      return true
    })
    formData = [
      ...formData,
      ...salvageData,
      ...partialData
    ]

    this.setState({
      inprogressConfig,
      formData: formData,
      configState: CONFIGSTATES['INPROGRESS']
    })

    let selectedAttributes = []
    formData.forEach(element => {
      selectedAttributes.push(...element.attributes)
    })
    this.props.updateClaimConfigData({
      selectedClaimsFormAttribute: selectedAttributes
    })
    Object.keys(responsesProvided).forEach((key) => {
      if (responsesProvided[key]['is_valid']) {
        delete responsesProvided[key]['is_valid']
      } else {
        delete responsesProvided[key]
      }
    })
    this.setState({ responsesProvided })
    delete responsesProvided[0]
    Object.keys(responsesProvided).forEach((response, index) => {
      Object.keys(responsesProvided[response]).map((label) => findAndReplaceKey(questions[index], 'name', label, 'default_answer', responsesProvided[response][label]))
    })
    this.setState({ questions })
    if (Object.keys(responsesProvided).length === questions.length) {
      this.setState({ configData: questions })
      this.handleStepChange(3)
    } else {
      this.handleStepChange(2)
    }
  }

  handleStepChange = (step) => {
    const { stepsConfig } = this.state
    let tempStepsConfig = stepsConfig
    for (let i = 0; i < step; i++) {
      tempStepsConfig[i].status = 'finish'
    }
    tempStepsConfig[step].status = 'process'
    this.setState({ current: step, stepsConfig: tempStepsConfig })
  }

  handleEditConfigData = (configData = {}) => {
    const { config_dump_data: configDumpData = {}, config_dump_id: configDumpId, slug } = configData
    const { responses_provided: responsesProvided, questions } = configDumpData

    let formData = responsesProvided[0] ? responsesProvided[0]['form_data'] : []
    let salvageData = responsesProvided[0] ? get(responsesProvided[0], 'salvage_data', []) : []
    let partialData = responsesProvided[0] ? get(responsesProvided[0], 'partial_data', []) : []

    formData.forEach(element => {
      element.formType = 'claim'
      return true
    })

    salvageData.forEach(element => {
      element.formType = 'salvage'
      return true
    })

    partialData.forEach(element => {
      element.formType = 'partial'
      return true
    })

    formData = [
      ...formData,
      ...salvageData,
      ...partialData
    ]

    this.setState({
      formData: formData,
      configDumpId,
      configData: responsesProvided,
      configSlug: slug
    })

    let selectedAttributes = []
    formData.forEach(element => {
      selectedAttributes.push(...element.attributes)
    })

    this.props.updateClaimConfigData({
      selectedClaimsFormAttribute: selectedAttributes
    })
    delete responsesProvided[0]
    Object.keys(responsesProvided).forEach((key) => {
      if (responsesProvided[key]['is_valid']) {
        delete responsesProvided[key]['is_valid']
      }
    })

    Object.keys(responsesProvided).forEach((response, index) => {
      Object.keys(responsesProvided[response]).map((label) => findAndReplaceKey(questions[index], 'name', label, 'default_answer', responsesProvided[response][label]))
    })
    this.setState({ questions, responsesProvided })
  }

  handleNext = () => {
    const { current, stepsConfig } = this.state
    let tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = 'finish'
    tempStepsConfig[current + 1].status = 'process'
    this.setState({ current: current + 1, stepsConfig: tempStepsConfig })
  }

  handlePrevious = () => {
    const { current, stepsConfig } = this.state
    let tempStepsConfig = stepsConfig
    tempStepsConfig[current].status = 'wait'
    tempStepsConfig[current - 1].status = 'process'
    this.setState({ current: current - 1, stepsConfig: tempStepsConfig })
  }

  saveQuestionnaireData = (data) => {
    this.setState({ configData: data })
  }

  saveResponse = (data, formData) => {
    this.setState({ configData: data, formData })
  }

  getQuestions = () => {
    const { claimsConfigTemplatesDetails = {} } = this.props
    const { configState, questions: stateQuestions } = this.state
    const { questions = [] } = claimsConfigTemplatesDetails

    switch (configState) {
      case CONFIGSTATES['INPROGRESS']:
      case CONFIGSTATES['EDIT']:
        return stateQuestions
      default:
        return questions
    }
  }

  checkThisAliasExist = (alias = "") => {
    const { aliasChosenByPO } = this.state

    if (aliasChosenByPO.includes(alias)) {
      return true
    } else {
      this.setState({
        aliasChosenByPO: [...aliasChosenByPO, alias.trim()]
      })
      return false
    }
  }

  deleteAliasFromLocalArray = (alias="") =>{
    const {aliasChosenByPO} = this.state

    if(aliasChosenByPO.includes(alias)){
      const temp = aliasChosenByPO.filter((al)=> al!==alias)
      this.setState({
        aliasChosenByPO: temp
      })
    }
  }

  render() {
    const { history, inprogressConfigLoading } = this.props
    const { stepsConfig, current, benefitId, configData, formData,
      inprogressConfig, configDumpId, configSlug, editData, configState, responsesProvided, partner, source
    } = this.state

    return (
      <AddConfigStyle>
        <Spin spinning={!!inprogressConfigLoading}>
          <Card>
            <Button
              type='primary'
              onClick={() => this.props.history.goBack()}
            >
              Back
            </Button>
            <div className='heading'>
              Wizard
            </div>
            <Steps current={current}>
              {
                stepsConfig.map(({ title, status, icon }, index) =>
                  <Step key={index} title={title} status={status} icon={<Icon type={icon} />} />
                )
              }
            </Steps>
            {
              current === 0 &&
              <Card>
                <ChooseTemplate
                  handleNext={this.handleNext}
                  handleInprogressConfigData={this.handleInprogressConfigData}
                  // configSource={source}
                  edit={configState === CONFIGSTATES['EDIT']}
                />
              </Card>
            }
            {
              current === 1 &&
              <Card>
                <AddForm
                  benefitId={benefitId}
                  handleNext={this.handleNext}
                  saveResponse={this.saveResponse}
                  formData={formData}
                  configDumpId={configDumpId}
                  configState={configState}
                  inprogressConfig={inprogressConfig}
                  partner={partner}
                  checkThisAliasExist={this.checkThisAliasExist}
                  deleteAliasFromLocalArray={this.deleteAliasFromLocalArray}
                />
              </Card>
            }
            {
              current === 2 &&
              <Card>
                <Questionnaire
                  benefitId={benefitId}
                  saveQuestionnaireData={this.saveQuestionnaireData}
                  handleNext={this.handleNext}
                  handlePrevious={this.handlePrevious}
                  configData={configData}
                  questions={this.getQuestions()}
                  inprogess={inprogressConfig}
                  configDumpId={configDumpId}
                  editData={editData}
                  configState={configState}
                  responsesProvided={responsesProvided}
                  inprogressConfig={inprogressConfig}
                />
              </Card>
            }
            {
              current === 3 &&
              <Card>
                <Review
                  configData={configData}
                  formData={formData}
                  history={history}
                  configSlug={configSlug}
                  handlePrevious={this.handlePrevious}
                  inprogressConfig={inprogressConfig}
                />
              </Card>
            }
            <Divider />
            {/* <Button
            type='primary'
            onClick={this.handlePrevious}
          >
            Provious
          </Button> */}
          </Card>
        </Spin>
      </AddConfigStyle>
    )
  }
}

export default connect(state => ({
  inprogressConfigLoading: state.Loading.GET_INPROGRESS_CONFIG,
  inprogressConfigError: state.Error.GET_INPROGRESS_CONFIG,
  inprogressConfig: state.Claims.inprogressConfig,
  inprogressConfigStatus: state.Claims.inprogressConfigStatus,
  claimsConfigTemplatesDetails: state.Claims.claimsConfigTemplatesDetails,
  claimConfigTemplateLoading: state.Loading.GET_CONFIG_TEMPLATES,
  claimConfigTemplate: state.Claims.claimConfigTemplate,
  getConfigTemplateDetailsLoading: state.Loading.GET_CONFIG_TEMPLATES_DETAILS,
  getConfigTemplateDetailsError: state.Error.GET_CONFIG_TEMPLATES_DETAILS,
  claimConfigData: state.Claims.claimConfigData
}), {
  getConfigTemplates,
  getConfigTemplateDetails,
  getInprogressConfig,
  getPolicyFormAttributes,
  updateClaimConfigData,
  resetLoadingRedux,
  resetErrorRedux
})(AddConfig)
