import { useEffect, useState } from 'react'
import { connect } from 'react-redux'
import { Form, Input, Button, Tooltip, Table, Icon, notification, Checkbox } from 'antd'
import fileUrls from '../../../../../request/urls/file'
import FileUploadOnGcsV2 from '../../../../../components/FileUploadOnGcsV2'
import extractUrl from '../../../../../helpers/extractUrl'
import { AddMetadataAttributeContainer, InfoContainer, ButtonContainer, WarningText } from './index.style'

import ClaimActions from '../../../../redux/claims/actions'
import LoadingActions from '../../../../../redux/loading/actions'
import ErrorActions from '../../../../../redux/error/actions'

const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions
const { verifyAliasExist, resetReduxStateClaim } = ClaimActions



const FormItem = Form.Item
export function getFileType(file) {

  if (!file) return 'image/png'

  if (file.startsWith('https')) {
    if (file.endsWith('png')) {
      return 'image/png'
    } if (file.endsWith('jpeg')) {
      return 'image/jpeg'
    } if (file.endsWith('jpg')) {
      return 'image/jpg'
    }
    if (file.endsWith('pdf')) {
      return 'application/pdf'
    }
    return 'image/png'
  }

  for (let i = 0; i < 100; i++) {
    if (file[i] === ';') {
      return file.slice(5, i)
    }
  }

}

function AddMetaAttribute(props) {
  const { userguidelineAction = "", attribute = {}, form, updateMetaAttribute, checkThisAliasExist,
    verifyAliasExistStatus, verifyAliasExistMessage, verifyAliasExist, existingUserGuidelineList = [],
    resetReduxStateClaim } = props
  const { getFieldDecorator } = form


  const [isViewMode, setIsViewMode] = useState(false)
  const [selectedMetadataInfo, setSelectedMetadataInfo] = useState(null)
  const [selectOrEditExistingMetadata, setSelectedOrEditExistingMetadata] = useState(null)
  const [filtredExistingUserGuidelineList, setFilteredExistingUserGuidelineList] = useState([])
  const { type = "", guideline: existedGuideline = {}, alias: existedAlias = "", user_guideline_id: userGuidelineId } = attribute
  const { placeholder: existedPlaceholder, disclaimer: existedDisclaimer, imageGuide: existedimageGuide = {} } = existedGuideline || {}

  useEffect(() => {
    if (userguidelineAction === 'view') {
      setIsViewMode(true)
    }
  }, [userguidelineAction])

  useEffect(() => {
    let temp = []
    if (type === 'image') {
      temp = existingUserGuidelineList.filter((guide) => {
        const { guideline = "{}" } = guide
        const { imageGuide = {} } = !!guideline ? JSON.parse(guideline) : {}
        if (imageGuide?.value) return true
        return false
      })
    } else {
      temp = existingUserGuidelineList.filter((guide) => {
        const { guideline = "{}" } = guide
        const { imageGuide = {} } = !!guideline ? JSON.parse(guideline) : {}
        if (imageGuide?.value) return false
        return true
      })
    }
    setFilteredExistingUserGuidelineList([...temp])

  }, [type, existingUserGuidelineList])

  useEffect(() => {
    if (selectOrEditExistingMetadata === 'edit') {
      const { guideline = "", alias } = selectedMetadataInfo
      const { imageGuide = {}, disclaimer = "", placeholder = "" } = guideline ? JSON.parse(guideline) : {}

      form.setFieldsValue({
        imageGuide: imageGuide?.value ? [{
          name: imageGuide.value,
          url: imageGuide.value,
          status: 'done',
          uid: 'id' + (new Date()).getTime()
        }] : null,
        disclaimer: disclaimer,
        placeholder: placeholder,
        alias,
      });
    }

  }, [selectOrEditExistingMetadata, selectedMetadataInfo])


  useEffect(() => {
    if (verifyAliasExistStatus && verifyAliasExistMessage === 'Success') {
      form.validateFields((err, values) => {
        if (err) {
          return
        }
        const { alias } = values
        if (checkThisAliasExist(alias)) {
          notification.error({
            message: 'Alias already exist'
          })
        } else {
          let imageGuide = extractUrl(values.imageGuide) ? extractUrl(values.imageGuide) : null
          const updatedValues = {
            ...values,
            imageGuide,
          }
          updateMetaAttribute(attribute, updatedValues, userguidelineAction)
        }
      })
      resetReduxStateClaim(['verifyAliasExistStatus', 'verifyAliasExistMessage'])
    } else if (verifyAliasExistStatus && verifyAliasExistStatus === 'Error') {
      notification.error({
        message: 'Alias already exist'
      })
      resetReduxStateClaim(['verifyAliasExistStatus', 'verifyAliasExistMessage'])
    }

  }, [verifyAliasExistStatus, verifyAliasExistMessage, resetReduxStateClaim, checkThisAliasExist, updateMetaAttribute, attribute, userguidelineAction])

  const deleteUserGuideline = () => {
    updateMetaAttribute(attribute, null, 'delete')
  }

  if (isViewMode) {
    let placeholder = ""
    let disclaimer = ""
    let imageGuide = ""
    let alias = ""
    const foundInfo = userGuidelineId && existingUserGuidelineList && existingUserGuidelineList.find(({ id }) => userGuidelineId === id)
    const guideline = JSON.parse(foundInfo?.guideline || "{}")
    placeholder = existedPlaceholder || guideline?.placeholder
    disclaimer = existedDisclaimer || guideline?.disclaimer
    imageGuide = Object.keys(existedimageGuide).length ? existedimageGuide : guideline?.imageGuide
    alias = foundInfo?.alias ? foundInfo?.alias : existedAlias

    return (
      <>
        {placeholder ?
          <InfoContainer>
            <div>Placeholder:</div>
            <div>{placeholder}</div>
          </InfoContainer>
          : null
        }
        {disclaimer ?
          <InfoContainer>
            <div>Disclaimer:</div>
            <div>{disclaimer}</div>
          </InfoContainer>
          : null
        }
        {alias ?
          <InfoContainer>
            <div>Alias:</div>
            <div>{alias}</div>
          </InfoContainer>
          : null
        }
        {imageGuide?.value ?
          <InfoContainer>
            <div>Userguide:</div>
            <div>
              <img
                src={imageGuide?.value}
                alt={imageGuide?.value}
                height="200px"
                width="200px"
              />
            </div>
          </InfoContainer>
          : null
        }
        <Button type="danger" onClick={deleteUserGuideline} style={{
          marginTop: 5
        }}>Delete</Button>
      </>
    )
  }


  const submit = (e) => {
    e.preventDefault()
    if (userguidelineAction === 'select_from_existing') {
      form.validateFields((err, values) => {
        if (err) {
          return
        }
        let imageGuide = extractUrl(values.imageGuide) ? extractUrl(values.imageGuide) : null
        const updatedValues = {
          ...values,
          imageGuide,
        }
        const { id } = selectedMetadataInfo
        updateMetaAttribute(attribute, updatedValues, 'edit_from_existing', id)
        form.resetFields();
      })
    } else if (userguidelineAction === 'create') {
      form.validateFields((err, values) => {
        if (err) {
          return
        }
        let imageGuide = extractUrl(values.imageGuide) ? extractUrl(values.imageGuide) : null
        const updatedValues = {
          ...values,
          imageGuide,
        }
        const payload = {
          attribute: {
            ...attribute,
            alias: updatedValues.alias && typeof updatedValues.alias === 'string' ? updatedValues.alias.trim() : '',
            guideline: {
              ...updatedValues
            }
          },
        }
        verifyAliasExist(payload)
      })
    }
  }

  if (userguidelineAction === 'create') {
    return (
      <Form onSubmit={submit} form={form} name="metadata-attribute">
        {
          type !== 'image' ?
            <FormItem label="Placeholder">
              {getFieldDecorator('placeholder', {
                rules: [
                  {
                    required: true,
                    message: 'This field is required.'
                  }
                ]
              })(
                <Input />
              )}
            </FormItem>
            : null
        }
        {
          type === 'image' ?
            <FormItem label="Disclaimer">
              {getFieldDecorator('disclaimer', {
              })(
                <Input />
              )}
            </FormItem>
            : null
        }
        <FormItem label="Alias for user guide">
          {
            getFieldDecorator('alias', {
              rules: [
                {
                  required: true,
                  message: 'This field is required.'
                }
              ]
            })(
              <Input
                placeholder='Add alias'
                disabled={userguidelineAction !== 'create'}
              />
            )
          }
        </FormItem>
        {
          type === 'image' ?
            <>
              <FileUploadOnGcsV2
                signedUrlEndPoint={fileUrls.generateSignedURL}
                getFieldDecorator={getFieldDecorator}
                makeFileUrlPublic
                required
                name='imageGuide'
                identifier='claims'
                minSize={0.00}
                form={form}
                maxFileAllowed={1}
                buttonText='Choose File'
                buttonClassName='fluid-width'
                icon='cloud-upload'
                maxSize={10}
                onPreview={false}
                accept='image/png,image/jpeg,image/jpg'
                fileNameLength={25}
                formItemProps={
                  { label: 'ImageGuide' }
                }
              />
            </> : null
        }
        <Button
          key="submit"
          type="primary"
          htmlType="submit"
          style={{
            marginTop: 5
          }}
        >
          Submit
        </Button>
      </Form>

    )
  }

  let searchInput = null
  const getColumnSearchProps = dataIndex => ({
    filterDropdown: ({ setSelectedKeys, selectedKeys, confirm, clearFilters }) => (
      <div style={{ padding: 8, marginTop: -20 }}>
        <Input
          ref={node => {
            searchInput = node
          }}
          placeholder={`Search ${dataIndex}`}
          value={selectedKeys?.[0]}
          onChange={e => setSelectedKeys(e.target.value ? [e.target.value] : [])}
          onPressEnter={confirm}
          style={{ width: 250, display: 'block' }}
        />
      </div>
    ),
    filterIcon: filtered => (
      <Icon type='search' style={{ color: filtered ? '#1890ff' : undefined }} />
    ),
    onFilter: (value, record) => {
      if (dataIndex === 'disclaimer' || dataIndex === 'placeholder') {
        const { guideline: stringifiedGuideline = "" } = record
        const guideline = stringifiedGuideline ? JSON.parse(stringifiedGuideline) : {}
        return guideline[dataIndex]
          .toString()
          .toLowerCase()
          .includes(value.toLowerCase())
      }
      return record[dataIndex]
        .toString()
        .toLowerCase()
        .includes(value.toLowerCase())
    },
    onFilterDropdownVisibleChange: visible => {
      if (visible) {
        setTimeout(() => searchInput.select())
      }
    }
  });

  const selectexistingGuide = (record, action) => {
    setSelectedMetadataInfo(record)
    setSelectedOrEditExistingMetadata(action)
  }

  const columns = [
    {
      title: 'Select',
      dataIndex: 'id',
      key: 'select',
      width: '70px',
      render: (_, record) => <div>
        <Checkbox onChange={() => selectexistingGuide(record, 'select')} checked={record.id === selectedMetadataInfo?.id} />
      </div>
    },
    {
      title: 'Partner',
      dataIndex: 'partner',
      key: 'partner',
      ...getColumnSearchProps('partner')
    },
    {
      title: 'Alias',
      dataIndex: 'alias',
      key: 'alias',
      render: (alias, record) => {
        const { guideline = "" } = record
        const { imageGuide = {}, placeholder = "" } = guideline ? JSON.parse(guideline) : {}
        return (
          <div>
            {imageGuide?.value
              ?
              <Tooltip placement="topLeft" title={<img src={imageGuide?.value} alt="guide" height="200px" width="200px" />}>
                <div>{alias || 'alias not available'}</div>
              </Tooltip> :
              placeholder
                ?
                <Tooltip placement='topLeft' title={`Placeholder - ${placeholder}`}>
                  <div>{alias || 'alias not available'}</div>
                </Tooltip>
                : null
            }
          </div>
        )
      },
      ...getColumnSearchProps('alias')
    },
    (type === 'image'
      ?
      {
        title: 'Disclaimer',
        dataIndex: 'guideline',
        key: 'disclaimer',
        width: '250px',
        render: (_, record) => {
          const { guideline = "" } = record
          const { disclaimer = "" } = guideline ? JSON.parse(guideline) : {}
          return (<span>
            {disclaimer}
          </span>)
        },
        ...getColumnSearchProps('disclaimer'),
        ellipsis: true,
      } : {}),
  ]

const saveSelectedMetadata = (values) => {
  const { id } = selectedMetadataInfo
  updateMetaAttribute(attribute, values, 'select_from_existing', id)
  form.resetFields();
}

  if (userguidelineAction === 'select_from_existing') {
    const { alias, guideline = "" } = selectedMetadataInfo || {}
    const { placeholder, disclaimer, imageGuide } = guideline ? JSON.parse(guideline) : {}
    return (
      <AddMetadataAttributeContainer>
        {filtredExistingUserGuidelineList && filtredExistingUserGuidelineList.length ?
          <Table
            columns={columns}
            dataSource={filtredExistingUserGuidelineList}
            pagination={{
              pageSize: 5,
            }}
          />
          : null}
        {
          !selectOrEditExistingMetadata
            ?
            <div>You have not chosen any existing any metadata</div>
            :
            selectOrEditExistingMetadata && selectOrEditExistingMetadata === 'select'
              ? (
                <>
                  {placeholder ?
                    <InfoContainer>
                      <div>Placeholder:</div>
                      <div>{placeholder}</div>
                    </InfoContainer>
                    : null
                  }
                  {disclaimer ?
                    <InfoContainer>
                      <div>Disclaimer:</div>
                      <div>{disclaimer}</div>
                    </InfoContainer>
                    : null
                  }
                  {
                    alias ?
                      <InfoContainer>
                        <div>Alias:</div>
                        <div>{alias}</div>
                      </InfoContainer>
                      : null
                  }
                  {imageGuide?.value ?
                    <InfoContainer>
                      <div>Userguide:</div>
                      <div>
                        <img
                          src={imageGuide?.value}
                          width="200px"
                          height="200px"
                          alt="imageguide"
                        />
                      </div>
                    </InfoContainer>
                    : null
                  }
                  <ButtonContainer>
                    <Button
                      type="primary"
                      onClick={() => selectexistingGuide(selectedMetadataInfo, 'edit')}>Edit</Button>
                    <Button
                      type="primary"
                      onClick={() => saveSelectedMetadata({
                        placeholder,
                        disclaimer,
                        imageGuide,
                        alias
                      })}>Submit</Button>
                  </ButtonContainer>

                </>
              )
              :
              <Form onSubmit={submit} name="metadata-attribute">
                <WarningText>
                  <p>
                    On editing these values these changes will also reflect on existing user guides (Alias is non-editable)
                  </p>
                  <p>
                    If you don't want the change to reflect on existing configured attributes, kindly create a new one.
                  </p>

                </WarningText>
              {
                type !== 'image' ?
                  <FormItem label="Placeholder">
                    {getFieldDecorator('placeholder', {
                      rules: [
                        {
                          required: true,
                          message: 'This field is required.'
                        }
                      ]
                    })(
                      <Input />
                    )}
                  </FormItem>
                  : null
              }
              {
                type === 'image' ?
                  <FormItem label="Disclaimer">
                    {getFieldDecorator('disclaimer', {
                    })(
                      <Input />
                    )}
                  </FormItem>
                  : null}
              <FormItem label="Alias for user guide">
                {
                  getFieldDecorator('alias', {
                    rules: [
                      {
                        required: true,
                        message: 'This field is required.'
                      }
                    ]
                  })(
                    <Input
                      placeholder='Add alias'
                      disabled={userguidelineAction !== 'create'}
                    />
                  )
                }
              </FormItem>
              {
                type === 'image' ?
                  <>
                    <FileUploadOnGcsV2
                      signedUrlEndPoint={fileUrls.generateSignedURL}
                      getFieldDecorator={getFieldDecorator}
                      makeFileUrlPublic
                      required
                      name='imageGuide'
                      identifier='claims'
                      minSize={0.00}
                      form={form}
                      maxFileAllowed={1}
                      buttonText='Choose File'
                      buttonClassName='fluid-width'
                      icon='cloud-upload'
                      maxSize={25}
                      onPreview={false}
                      accept='image/png,image/jpeg,image/jpg'
                      fileNameLength={25}
                      formItemProps={
                        { label: 'ImageGuide' }
                      }
                    />
                  </> : null
              }
              <Button
                key="submit"
                type="primary"
                htmlType="submit"
                style={{
                  marginTop: 5
                }}
              >
                Submit
              </Button>
            </Form>
      }
    </AddMetadataAttributeContainer>
  )
}

return null

}

const WrappedAddForm = Form.create()(AddMetaAttribute)

export default connect(state => ({
  verifyAliasExistStatus: state.Claims.verifyAliasExistStatus,
  verifyAliasExistMessage: state.Claims.verifyAliasExistMessage,
}), {
  resetLoadingRedux,
  resetErrorRedux,
  verifyAliasExist,
  resetReduxStateClaim
})(WrappedAddForm)