import React, { Component } from 'react'
import { connect } from 'react-redux'
import { clone, get, remove } from 'lodash'
import { Form, Input, Select, Button, notification, Row, Col, Spin, Radio, Modal } from 'antd'

import LoadingActions from '../../../../../redux/loading/actions'
import ErrorActions from '../../../../../redux/error/actions'
import ClaimActions from '../../../../redux/claims/actions'
import { AddFormStyle } from './index.style'
import SelectedAttributesTable from './components/SelectedAtrributesTable'
import AddMetaAttribute from './AddMetdataAttribute'

const { resetLoadingRedux } = LoadingActions
const { resetErrorRedux } = ErrorActions
const { getExistingUserguidelineList, verifyAliasExist } = ClaimActions

const FormItem = Form.Item
const { TextArea } = Input
const { Option } = Select

const options = [
  { label: 'Claim form', value: 'claim' },
  { label: 'Salvage Form', value: 'salvage' },
  { label: 'Partial Form', value: 'partial' }
]

// if (process.env.REACT_APP_ENV !== 'production') {
//   options.push({ label: 'Partial Form', value: 'partial' })
// }
function addKeyFieldInObj (attributes = []) {
  return attributes.map((attribute, index) => {
    return {
      ...attribute,
      key: index
    }
  })
}

class AddForm extends Component {
  constructor (props) {
    super(props)
    this.state = {
      selectedAttributes: [],
      formData: {},
      alias: {},
      metadata: {}
    }
  }

  componentDidMount () {
    this.props.resetLoadingRedux(['FORM_CREATE', 'UPDATE_FORM', 'FORM_DETAIL'])
    this.props.resetErrorRedux(['FORM_CREATE', 'UPDATE_FORM', 'FORM_DETAIL'])

    this.props.getExistingUserguidelineList()

    this.setState({ filteredAttributeList: this.removeAlreadySelectedAttributes(clone(this.props.searchAttributeResult), this.props.selectedAttributes) },
      () => {
        const { editData = {} } = this.props
        if (Object.keys(editData).length > 0) {
          editData.attributes.forEach(element => {
            this.handleAttributeSearch(get(element, 'name'))
          })
          this.setState({ formData: this.props.editData, selectedAttributes: addKeyFieldInObj(this.props.editData.attributes) })
        }
      }
    )
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      editData,
      searchAttributeResult,
      selectedAttributes
    } = nextProps
    const { formData } = this.state

    if (formData !== editData) {
      if (Object.keys(editData).length > 0) {
        editData.attributes.forEach(element => {
          this.handleAttributeSearch(get(element, 'name'))
        })
      }
      this.setState({ formData: editData, selectedAttributes: addKeyFieldInObj(get(editData, 'attributes', [])), filteredAttributeList: this.removeAlreadySelectedAttributes(clone(searchAttributeResult), selectedAttributes) })
    } else if (this.props.selectedAttributes !== selectedAttributes) {
      this.setState({ filteredAttributeList: this.removeAlreadySelectedAttributes(clone(searchAttributeResult), selectedAttributes) })
    }
  }

  handleSubmit = (e) => {
    e.preventDefault()
    this.props.form.validateFields((err, values) => {
      if (!err) {
        const { editID, partner } = this.props
        const { selectedAttributes = [], formData } = this.state
        if (!selectedAttributes.length) {
          return notification.error({ message: 'Please select document(s)!' })
        }
        const formSelectedAttributes = selectedAttributes.map((attribute, index) => {
          delete attribute.key
          attribute.visual_order = index + 1
          attribute.partner = partner
          return attribute
        })
        values = {
          ...values,
          attributes: formSelectedAttributes,
          form_slug: get(formData, 'form_slug'),
          salvage_slug: get(formData, 'salvage_slug')
        }
        this.props.saveFormData(values, editID)
        this.handleCancel()
      }
    })
  }

  handleAddAttribute = () => {
    const { selectedAttributes = [], searchAttribute } = this.state

    if (!searchAttribute) {
      return notification.error({ message: 'Please select attribute' })
    }

    let tempSelectedAttributes = selectedAttributes
    const parsedAttribute = JSON.parse(searchAttribute)
    tempSelectedAttributes = [
      ...tempSelectedAttributes,
      {
        master_attribute_id: parsedAttribute.id,
        name: parsedAttribute.name,
        label: parsedAttribute.label,
        required: false,
        is_internal: parsedAttribute.is_internal,
        validation_required: false,
        is_multiple_value_required: false,
        type: parsedAttribute.type,
        key: parseInt(selectedAttributes[selectedAttributes.length - 1]?.key || 0) + 1
      }
    ]
    this.setState({
      selectedAttributes: tempSelectedAttributes,
      filteredAttributeList: this.handleAttributeSearch(parsedAttribute.name),
      searchAttribute: undefined
    }, () => this.props.form.setFieldsValue({ searchAttribute: undefined }))
  }

  handleSelectRegex = (index, value) => {
    const { selectedAttributes } = this.state
    const tempSelectedAttributes = selectedAttributes
    tempSelectedAttributes[index] = {
      ...tempSelectedAttributes[index],
      regex: value
    }
    this.setState({ selectedAttributes: tempSelectedAttributes })
  }

  handleChangeLabel = (index, value) => {
    const { selectedAttributes } = this.state
    const tempSelectedAttributes = selectedAttributes
    tempSelectedAttributes[index] = {
      ...tempSelectedAttributes[index],
      label: value
    }
    this.setState({ selectedAttributes: tempSelectedAttributes })
  }

  handleAttributeDelete = (index, attribute) => {
    const { selectedAttributes } = this.state
    const tempSelectedAttributes = [...selectedAttributes]

    tempSelectedAttributes.splice(index, 1)
    this.setState({ selectedAttributes: tempSelectedAttributes }, () => this.addAttribute(attribute))
  }

  handleGuidelineAction = (index, attribute, action) => {
    if (['create', 'select_from_existing', 'view'].includes(action)) {
      this.setState({
        isModalOpen: true,
        metadataAttribute: attribute,
        userguidelineAction: action
      })
    }
  }

  showViewOption = (record) => {
    if (record?.guideline) {
      return true
    }

    if (record?.user_guideline_id) {
      return true
    }

    return false
  }

  addAttribute = (attribute) => {
    const { filteredAttributeList = [] } = this.state
    const tempFilteredAttributeList = [...filteredAttributeList]
    tempFilteredAttributeList.push(attribute)
    this.setState({ filteredAttributeList: tempFilteredAttributeList })
  }

  handleCheckboxChange = (index, key, value) => {
    const { selectedAttributes } = this.state
    const tempSelectedAttributes = selectedAttributes
    tempSelectedAttributes[index][key] = value
    this.setState({ selectedAttributes: tempSelectedAttributes })
  }

  handleCancel = () => {
    const { searchAttributeResult } = this.props
    this.props.form.resetFields()
    this.setState({
      filteredAttributeList: searchAttributeResult,
      selectedAttributes: []
    }, () => this.props.onHandleCancel())
  }

  handleAttributeSearch = (attributeName) => {
    const { filteredAttributeList = [] } = this.state
    try {
      remove(filteredAttributeList, { name: attributeName })
      return filteredAttributeList
    } catch (e) {
      return filteredAttributeList || []
    }
  }

  removeAlreadySelectedAttributes = (attributes, selectedAttributes) => {
    selectedAttributes && selectedAttributes.length && selectedAttributes.forEach(element => {
      remove(attributes, { name: element.name })
    })
    return attributes
  }

  handleHideModal = () => {
    this.setState({
      isModalOpen: false,
      metadataAttribute: null
    })
  }

  submitMetadata = (attribute, values, action, userGuidelineId) => {
    const { selectedAttributes } = this.state
    const { partner, deleteAliasFromLocalArray } = this.props
    const { master_attribute_id: id } = attribute
    if (!!values && action === 'create') {
      const tempSelectedAttributes = selectedAttributes.map((att) => {
        if (id === att.master_attribute_id) {
          return {
            ...att,
            alias: values.alias && typeof values.alias === 'string' ? values.alias.trim() : values.alias,
            partner: partner,
            create_user_guideline: true,
            delete_user_guideline: undefined,
            user_guideline_id: undefined,
            guideline: {
              placeholder: values.placeholder,
              disclaimer: values.disclaimer || null,
              imageGuide: {
                value: values.imageGuide || null
              }
            }
          }
        }
        return att
      })
      this.setState({
        selectedAttributes: tempSelectedAttributes
      })
    }

    if (action === 'delete') {
      const tempSelectedAttributes = selectedAttributes.map((att) => {
        if (id === att.master_attribute_id) {
          return {
            ...att,
            partner: partner,
            alias: undefined,
            guideline: null,
            user_guideline_id: undefined,
            create_user_guideline: undefined,
            delete_user_guideline: true
          }
        }
        return att
      })
      this.setState({
        selectedAttributes: tempSelectedAttributes
      })
      deleteAliasFromLocalArray(attribute.alias || '')
    }

    if (action === 'select_from_existing') {
      const tempSelectedAttributes = selectedAttributes.map((att) => {
        if (id === att.master_attribute_id) {
          return {
            ...att,
            partner: partner,
            alias: undefined,
            guideline: undefined,
            create_user_guideline: undefined,
            delete_user_guideline: undefined,
            user_guideline_id: userGuidelineId
          }
        }
        return att
      })
      this.setState({
        selectedAttributes: tempSelectedAttributes
      })
    }

    if (action === 'edit_from_existing') {
      const tempSelectedAttributes = selectedAttributes.map((att) => {
        if (id === att.master_attribute_id) {
          return {
            ...att,
            alias: values.alias && typeof values.alias === 'string' ? values.alias.trim() : values.alias,
            partner: partner,
            user_guideline_id: userGuidelineId,
            create_user_guideline: undefined,
            delete_user_guideline: undefined,
            guideline: {
              placeholder: values.placeholder,
              disclaimer: values.disclaimer || null,
              imageGuide: {
                value: values.imageGuide || null
              }
            }
          }
        }
        return att
      })
      this.setState({
        selectedAttributes: tempSelectedAttributes
      })
    }

    this.hideModal()
  }

  render () {
    const {
      form, searchAttributeLoading,
      formCreateLoading, getFormDetailLoading, regexList, existingUserGuidelineList,
      checkThisAliasExist
    } = this.props
    const { getFieldDecorator } = form
    const {
      selectedAttributes = [], formData = {}, filteredAttributeList = [], isModalOpen,
      metadataAttribute, metadata, userguidelineAction, alias
    } = this.state

    return (
      <>
        <AddFormStyle>
          <Spin spinning={!!formCreateLoading || !!getFormDetailLoading}>
            <Form>
              <FormItem>
                {getFieldDecorator('formType', {
                  initialValue: formData.formType || 'claim'
                })(
                  <Radio.Group options={options} />
                )}
              </FormItem>
              <FormItem label='Form Name'>
                {getFieldDecorator('title', {
                  rules: [{ required: true, message: 'Please input display name!' }],
                  initialValue: formData.title
                })(
                  <Input
                    placeholder='Form Name'
                  />
                )}
              </FormItem>
              <FormItem label='Description'>
                {getFieldDecorator('description', {
                  rules: [{ required: true, message: 'Please input description!' }],
                  initialValue: formData.description
                })(
                  <TextArea
                    placeholder='Description'
                  />
                )}
              </FormItem>
              <div className='attribute-heading'>Add Documents</div>
              <SelectedAttributesTable
                classInstanceThis={this}
                regexList={regexList}
                dataSource={selectedAttributes}
              />
              <Row type='flex' className='attribute-row'>
                <Col className='attributee-col'>
                  <FormItem>
                    {getFieldDecorator('searchAttribute')(
                      <Select
                        showSearch
                        className='attribute-select'
                        placeholder='Search Document'
                        filterOption={(input, option) => option.props.children.toLowerCase().includes(input.toLowerCase())}
                        onChange={value => this.setState({ searchAttribute: value })}
                        loading={!!searchAttributeLoading}
                        disabled={!!searchAttributeLoading}
                        dropdownMatchSelectWidth={false}
                      >
                        {
                          filteredAttributeList.map((attribute) =>
                            <Option key={attribute.id} value={JSON.stringify(attribute)}>
                              {
                                `${attribute.name} - ${attribute.type}${attribute.is_internal ? '(Internal)' : ''}`
                              }
                            </Option>
                          )
                        }
                      </Select>
                    )}
                  </FormItem>
                </Col>
                <Col className='attributee-col'>
                  <Button
                    className='add-attribute-button'
                    onClick={this.handleAddAttribute}
                  >
                    Add Document
                  </Button>
                </Col>
              </Row>
              <Row type='flex' justify='space-around'>
                <Button
                  type='danger'
                  onClick={this.handleCancel}
                >
                  Cancel
                </Button>
                <Button
                  type='primary'
                  onClick={this.handleSubmit}
                >
                  Submit
                </Button>
              </Row>
            </Form>
          </Spin>
        </AddFormStyle>
        <Modal
          title='Add Userguideline'
          width={600}
          visible={isModalOpen}
          onCancel={this.handleHideModal}
          footer={null}
        >
          {metadataAttribute
            ? <AddMetaAttribute
                metadata={metadata}
                attribute={metadataAttribute}
                updateMetaAttribute={this.submitMetadata}
                existingUserGuidelineList={existingUserGuidelineList}
                userguidelineAction={userguidelineAction}
                checkThisAliasExist={checkThisAliasExist}
                existAliasData={alias}
              />
            : null}
        </Modal>
      </>
    )
  }
}

const WrappedAddForm = Form.create()(AddForm)

export default connect(state => ({
  searchAttributeLoading: state.Loading.SEARCH_ATTRIBUTE,
  searchAttributeError: state.Error.SEARCH_ATTRIBUTE,
  searchAttributeResult: state.Claims.searchAttributeResult.attributes,

  regexList: state.Claims.regexList,
  existingUserGuidelineList: state.Claims.existingUserGuidelineList,
  existingUserGuidelineMessage: state.Claims.existingUserGuidelineMessage
}), {
  resetLoadingRedux,
  resetErrorRedux,
  getExistingUserguidelineList,
  verifyAliasExist
})(WrappedAddForm)
