import axios from 'axios';
import lodash from 'lodash/object';
import { getHeader } from '../../helpers/utility'


const BASE_URL = process.env.REACT_APP_API_ENDPOINT
const BASE_PATH = '/api/claims/'

const makeFileUrlPublicCall = ({
  fileList
}) => {
  const combinedSignedUrl = `${BASE_URL}${BASE_PATH}make-url-public/`
  const requestPayload = {}
  lodash.set(requestPayload, 'makeFileUrlPublic', fileList )
  return axios
    .post(combinedSignedUrl, requestPayload, { headers: getHeader() })
    .then((res)=>{
      return res
    })
    .catch((err)=>{
      console.log('error in const makeFileUrlPublicCall = ({', err)
    })
}
export default makeFileUrlPublicCall
